        id: c.id + '-' + abbr,
        _gid: c.id,
        _custom: true,
        cat: c.cat || 'it',
        name: E(c.name || 'Custom Obligation'),
        due,
        freq: E(c.freq || 'Monthly'),
        form: E(c.form || ''),
        who: E(c.who || ''),
        what: E(c.what || ''),
        why: E(c.why || ''),
        penalty: E(c.penalty || ''),
        // Control-profile overrides flow through so getControlProfile honours them.
        responsible: E(c.responsible || ''),
        reviewer: E(c.reviewer || ''),
        risk: c.risk || '',
